import itertools
def normalised(result):
    """Check the shape of the answer (a list of lists), then sort the list of permutations. Their order does not matter; the order inside each one does."""
    if not isinstance(result, list) or not all(isinstance(arrangement, list) for arrangement in result):
        raise AssertionError(f"expected a list of lists, got {result!r}"[:200])
    return sorted(result)
def every_arrangement(values):
    """The same answer worked out another way, with itertools."""
    return sorted(list(arrangement) for arrangement in itertools.permutations(values))
